Source code in <code>streamo/config.py</code> <pre><code>def run(self, *, preview: bool = False) -&gt; int:
    from . import control, streamer

    self.validate_media()
    service_adapter = (
        GenericServiceAdapter(self.streaming_service)
        if preview
        else adapter_for(self.streaming_service)
    )
    controller = control.ControlController(
        state=RuntimeState(self.health_warnings),
        image_dir=self.incoming_image_dir,
        service=None if preview else service_adapter,
        closing=ClosingSequence(
            self.resolved_closing_credits, self.closing_state_path
        ),
    )
    controller.state.configure_service(service_adapter)
    if preview:
        controller.state.capabilities = []
    object.__setattr__(self, '_controller', controller)
    image_feed_poller = (
        None
        if self.image_feed is None
        or not self.live_overlays
        or self.streaming_service.encoding.video is None
        else ImageFeedPoller(self.image_feed, self.incoming_image_dir)
    )
    initial_image_paths = {
        p
        for d in [*self.image_dir, self.incoming_image_dir]
        for p in image_paths(d)
    }
    self.start()
    try:
        if image_feed_poller is not None:
            image_feed_poller.start()
        returncode = streamer.stream(
            self,
            controller,
            service_adapter,
            initial_image_paths=initial_image_paths,
            preview=preview,
        )
        if returncode:
            self.publish_error(
                str(
                    controller.state.snapshot()['last_error']
                    or f'ffmpeg exited with {returncode}'
                )
            )
        if controller.closing is not None and (
            controller.closing.snapshot()['state'] == 'completed'
        ):
            while not streamer.should_stop(controller):
                time.sleep(0.1)
        return returncode
    finally:
        if image_feed_poller is not None:
            image_feed_poller.stop()
        self.close()
