Source code in <code>streamo/youtube_api.py</code> <pre><code>def request(
    self,
    method: str,
    endpoint: str,
    *,
    query: Mapping[str, object] | None = None,
    body: Mapping[str, object] | None = None,
) -&gt; dict[str, object]:
    url = f'{self.api_url.rstrip("/")}/{endpoint}'
    if query:
        url = f'{url}?{urllib.parse.urlencode(query)}'
    encoded = None if body is None else json.dumps(body).encode()
    for attempt in range(2):
        token = self.tokens.access_token(force_refresh=attempt == 1)
        status, data = self.transport(
            YouTubeRequest(
                method=method,
                url=url,
                headers={
                    'Authorization': f'Bearer {token}',
                    'Content-Type': 'application/json',
                },
                body=encoded,
            )
        )
        if status == 401 and attempt == 0:
            continue
        if not 200 &lt;= status &lt; 300:
            raise YouTubeApiError(youtube_error(status, data))
        if not data:
            return {}
        try:
            result = json.loads(data)
        except (UnicodeDecodeError, json.JSONDecodeError) as error:
            raise YouTubeApiError('YouTube API returned invalid JSON') from error
        if not isinstance(result, dict):
            raise YouTubeApiError('YouTube API response was not an object')
        return result
    raise AssertionError('unreachable')
</code></pre>

Source code in <code>streamo/youtube_api.py</code> <pre><code>def urllib_transport(request: YouTubeRequest) -&gt; tuple[int, bytes]:
    url_request = urllib.request.Request(
        request.url,
        data=request.body,
        headers=request.headers,
        method=request.method,
    )
    try:
        with urllib.request.urlopen(url_request, timeout=10) as response:
            return response.status, response.read()
    except urllib.error.HTTPError as error:
        return error.code, error.read()
    except urllib.error.URLError as error:
        raise YouTubeApiError(f'YouTube API request failed: {error.reason}') from error
